// WF-00 · Verificación de firma, ventana temporal y origen.
//
// Primera barrera del SOAR. Todo lo que pase de aquí se considera una alerta
// auténtica de un colector autorizado.

// @blinksec-inject: lib/gateway.js

const item = $input.first();
const req = item.json;

// n8n 1.72 entrega el cuerpo crudo como adjunto binario en base64, NO en
// $json.rawBody. extractRawBody() cubre ambas formas.
const rawBody = extractRawBody(item);

const secrets = {
  splunk: $env.BLINKSEC_HMAC_SECRET_SPLUNK,
  elastic: $env.BLINKSEC_HMAC_SECRET_ELASTIC,
};

const windowSeconds = Number($env.BLINKSEC_REPLAY_WINDOW_SECONDS || 300);

try {
  const verificado = verifyRequest(
    { headers: req.headers, rawBody },
    { secrets, windowSeconds },
  );

  return [
    {
      json: {
        ok: true,
        source: verificado.source,
        rawBody: verificado.rawBody,
        receivedAt: new Date().toISOString(),
        ingestStartedAt: Date.now(),
      },
    },
  ];
} catch (e) {
  // No se propaga la excepción: se devuelve un objeto de rechazo para que el
  // nodo IF responda con el código correcto y WF-99 registre el intento.
  // Un webhook que devuelve 500 ante una firma inválida le está diciendo al
  // atacante que su petición llegó a la lógica de negocio.
  return [
    {
      json: {
        ok: false,
        rejectionCode: e.code || 'error_desconocido',
        rejectionMessage: e.message,
        httpStatus: e.httpStatus || 401,
        sourceHeader: req.headers?.['x-blinksec-source'] || null,
        remoteIp: req.headers?.['x-real-ip'] || null,
      },
    },
  ];
}

// WF-00 · Extracción del identificador determinista de la alerta.
//
// El alert_id es la clave de idempotencia de todo el sistema. Se deriva del
// contenido, no se genera al azar: si el SIEM reenvía la misma alerta (timeout
// y reintento, doble configuración de integración), debe producir el mismo id
// para que se descarte en vez de abrir un segundo ticket y ejecutar la
// contención dos veces.

// @blinksec-inject: lib/gateway.js

const item = $input.first().json;
const source = item.source;

let body;
try {
  body = JSON.parse(item.rawBody);
} catch (e) {
  // Elastic puede enviar ndjson o arrays con coma terminal. Aquí sólo hace
  // falta un identificador; el saneado completo lo hace WF-01.
  const primera = item.rawBody.split('\n')[0].replace(/,\s*([\]}])/g, '$1');
  body = JSON.parse(primera.startsWith('[') ? primera.slice(1) : primera);
}

const extractores = {
  splunk: (b) => ({
    ruleId: b.search_name || b.sid,
    eventTimestamp: b.result?._time,
    host: b.result?.host || b.result?.dest,
    srcIp: b.result?.src_ip,
  }),
  elastic: (b) => {
    const c = b.context || b;
    return {
      ruleId: c.rule?.id,
      eventTimestamp: c['@timestamp'],
      host: c.host?.name,
      srcIp: c.source?.ip,
    };
  },
};

const partes = extractores[source](body);
const alertId = deriveAlertId(source, partes);

return [
  {
    json: {
      ...item,
      alertId,
      idempotencyKey: `blinksec:nonce:${alertId}`,
      agentId: body.agent?.id ?? null,
    },
  },
];

// WF-00 · Telemetría de rechazos.
//
// Un pico de rechazos es una señal de seguridad de primer orden: o alguien
// está sondeando el webhook, o una integración legítima se rompió tras una
// rotación de secreto. Ambos casos exigen aviso; distinguirlos es trabajo del
// analista, no del flujo.

const r = $input.first().json;

return [
  {
    json: {
      evento: 'ingesta_rechazada',
      codigo: r.rejectionCode,
      origen: r.sourceHeader,
      ip: r.remoteIp,
      timestamp: new Date().toISOString(),
      // Los fallos de firma tras una rotación son ruidosos pero benignos.
      // Los de origen desconocido son casi siempre sondeo.
      severidad: r.rejectionCode === 'origen_desconocido' ? 'alta' : 'media',
    },
  },
];
